BEGIN;
TRUNCATE titik, area_sekolah, jalur, jalan RESTART IDENTITY;
SELECT setval(pg_get_serial_sequence('titik','id'), GREATEST((SELECT MAX(id) FROM titik), 1));
SELECT setval(pg_get_serial_sequence('area_sekolah','id'), GREATEST((SELECT MAX(id) FROM area_sekolah), 1));
SELECT setval(pg_get_serial_sequence('jalur','id'), GREATEST((SELECT MAX(id) FROM jalur), 1));
SELECT setval(pg_get_serial_sequence('jalan','id'), GREATEST((SELECT MAX(id) FROM jalan), 1));
COMMIT;
